+.brand{display:flex;align-items:center;gap:12px;text-decoration:none}
+.logo{
+  width:40px;height:40px;border-radius:14px;
+  background: radial-gradient(120% 120% at 20% 20%, rgba(255,255,255,.55), transparent 55%),
