+.nav-links{display:flex;gap:18px;align-items:center}
+.nav-links a{font-weight:700;color:rgba(11, 16, 32, .78);text-decoration:none;padding:10px 10px;border-radius:12px;transition:background .2s ease,color .2s ease}
+.nav-links a:hover{background:rgba(47, 91, 255, .08);color:rgba(11, 16, 32, .96)}
+.nav-links a[aria-current="page"]{background:rgba(47, 91, 255, .12);color:rgba(11, 16, 32, .96)}
+
+.nav-cta{display:flex;gap:10px;align-items:center}
+.menu-btn{display:none}
+
+@media (max-width: 900px){
+  .menu-btn{display:inline-flex}
+  .nav-links{display:none}
