+  overflow:hidden;
+}
+.preview-top{
+  display:flex;align-items:center;justify-content:space-between;
+  padding:12px 14px;border-bottom:1px solid rgba(17,24,39,.10)
+}
+.tabs{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
