+.mini-ui{
+  border-radius:18px;
+  border:1px solid rgba(17,24,39,.10);
+  background: linear-gradient(180deg, rgba(255,255,255,.9), rgba(255,255,255,.76));
+  overflow:hidden;
+}
+.mini-ui .row{display:flex;gap:10px;align-items:center}
