+@media (max-width: 960px){.logos{grid-template-columns: repeat(3, minmax(0, 1fr))}}
+@media (max-width: 520px){.logos{grid-template-columns: repeat(2, minmax(0, 1fr))}}
+
+/* Footer */
+footer{border-top:1px solid rgba(17,24,39,.08);padding:32px 0;background:rgba(2,6,23,.02)}
+.footer-grid{display:grid;grid-template-columns: 1.4fr repeat(4, 1fr);gap:18px}
