+.footer-grid a:hover{color:rgba(11,16,32,.92)}
+.fineprint{margin-top:18px;color:rgba(11,16,32,.58);font-size:.9rem}
+@media (max-width: 960px){.footer-grid{grid-template-columns:1fr 1fr}}
+
+/* Micro-animations on scroll */
+[data-animate]{opacity:0;transform: translateY(12px);transition: opacity .6s ease, transform .6s ease}
+[data-animate].in{opacity:1;transform: translateY(0)}
+
+@keyframes fadeUp{from{opacity:.0;transform: translateY(8px)}to{opacity:1;transform: translateY(0)}}
+
+/* Utility */
+.muted{color:var(--muted)}
+.center{text-align:center}
+.mt-10{margin-top:10px}
+.mt-16{margin-top:16px}
+.mt-22{margin-top:22px}
+.mt-28{margin-top:28px}
+.tag{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 12px;border-radius:999px;
+  border:1px solid rgba(17,24,39,.10);
+  background:rgba(2,6,23,.02);
+  font-weight:800;color:rgba(11,16,32,.78)
+}
+.tag b{color:rgba(11,16,32,.94)}
+
*** End Patch
PATCH

